package nl.slimov.app;
import android.app.job.*;import android.content.*;import org.json.*;import java.util.*;
/** Periodic system job: no permanent socket or private server for alert subscriptions. */
public final class AlertJob extends JobService {
 private volatile boolean stopped;private Thread worker;
 @Override public boolean onStartJob(JobParameters params){stopped=false;worker=new Thread(()->{try{check(this);}catch(Exception ignored){}if(!stopped)jobFinished(params,false);},"SlimOV-alerts");worker.start();return true;}
 @Override public boolean onStopJob(JobParameters params){stopped=true;if(worker!=null)worker.interrupt();return true;}
 public static void schedule(Context c,JSONObject config){android.content.SharedPreferences prefs=c.getSharedPreferences("watch",0);boolean changed=!prefs.getString("alerts","{}").equals(config.toString());android.content.SharedPreferences.Editor editor=prefs.edit().putString("alerts",config.toString());if(changed)editor.putBoolean("alertsBaseline",false).remove("seenAlerts");editor.apply();JobScheduler scheduler=c.getSystemService(JobScheduler.class);scheduler.cancel(38);if(!config.optBoolean("enabled"))return;long interval=Math.max(15,Math.min(120,config.optInt("minutes",30)))*60000L;scheduler.schedule(new JobInfo.Builder(38,new ComponentName(c,AlertJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPeriodic(interval).setPersisted(true).build());}
 private static Set<String> values(JSONArray a){Set<String> out=new HashSet<>();if(a!=null)for(int i=0;i<a.length();i++)out.add(a.optString(i).replaceFirst("^nl-OpenOV_",""));return out;}
 private static boolean intersects(JSONArray a,Set<String> b){if(a!=null)for(int i=0;i<a.length();i++)if(b.contains(a.optString(i).replaceFirst("^nl-OpenOV_","")))return true;return false;}
 public static synchronized void check(Context c)throws Exception{android.content.SharedPreferences prefs=c.getSharedPreferences("watch",0);String rawConfig=prefs.getString("alerts","{}");JSONObject cfg=new JSONObject(rawConfig);if(!cfg.optBoolean("enabled"))return;Set<String> placeRoutes=values(cfg.optJSONArray("placeRoutes"));Set<String> routes=values(cfg.optJSONArray("routes")),stops=values(cfg.optJSONArray("stops")),agencies=values(cfg.optJSONArray("agencies"));boolean routeFilter=cfg.optBoolean("routeFilter"),stopFilter=cfg.optBoolean("stopFilter");if(routes.isEmpty()&&stops.isEmpty()&&agencies.isEmpty())return;JSONObject old=new JSONObject(prefs.getString("seenAlerts","{}")),current=new JSONObject();boolean baseline=prefs.getBoolean("alertsBaseline",false);JSONArray list=MonitorNetwork.alerts().getJSONArray("alerts");int count=0;String first="";long now=System.currentTimeMillis()/1000;
  for(int i=0;i<list.length();i++){JSONObject a=list.getJSONObject(i);boolean active=a.optJSONArray("periods")==null||a.optJSONArray("periods").length()==0;JSONArray periods=a.optJSONArray("periods");if(periods!=null)for(int j=0;j<periods.length();j++){JSONObject p=periods.getJSONObject(j);if((p.optLong("start")==0||p.optLong("start")<=now)&&(p.optLong("end")==0||p.optLong("end")>=now))active=true;}if(!active)continue;boolean byRoute=intersects(a.optJSONArray("routes"),routes),byStop=intersects(a.optJSONArray("stops"),stops),byAgency=intersects(a.optJSONArray("agencies"),agencies);boolean byPlace=byStop||intersects(a.optJSONArray("routes"),placeRoutes);if(!cfg.optString("carrier").isEmpty()&&!byRoute&&!byAgency||routeFilter&&!byRoute||stopFilter&&!byPlace||!routeFilter&&!stopFilter&&!byRoute&&!byAgency&&!byStop)continue;String id=a.optString("id"),signature=Integer.toHexString((a.optString("title")+a.optString("description")+a.optInt("effect")+a.optInt("cause")+String.valueOf(a.optJSONArray("periods"))+String.valueOf(a.optJSONArray("stops"))+String.valueOf(a.optJSONArray("routes"))).hashCode());current.put(id,signature);if(baseline&&(!old.has(id)||cfg.optBoolean("changes",true)&&!signature.equals(old.optString(id)))){count++;if(first.isEmpty())first=a.optString("title","Nieuwe OV-melding");}}
  if(!rawConfig.equals(prefs.getString("alerts","{}")))return;prefs.edit().putString("seenAlerts",current.toString()).putBoolean("alertsBaseline",true).putLong("alertsCheckedAt",System.currentTimeMillis()).apply();if(count>0)Notice.send(c,38,count==1?"Nieuwe of gewijzigde OV-melding":count+" nieuwe of gewijzigde OV-meldingen",first);
 }
}
